import {builtInReply} from './guide-core.js';
const launcher=document.createElement('button');launcher.id='radar-launcher';launcher.className='radar-launcher';launcher.textContent='✦ Ask Radar';launcher.setAttribute('aria-haspopup','dialog');launcher.setAttribute('aria-controls','radar-dialog');document.body.append(launcher);
const dialog=document.createElement('dialog');dialog.id='radar-dialog';dialog.setAttribute('aria-labelledby','radar-title');
dialog.innerHTML=`<header class="radar-header"><div><span>YOUR BUILDING COMPANION</span><h2 id="radar-title">A little guidance.<br>A clearer next step.</h2></div><button id="radar-close" aria-label="Close Radar guide">×</button></header><div class="radar-toolbar"><label for="radar-mode">Reply source</label><select id="radar-mode"><option value="guide">Built-in help</option><option value="live" disabled>Live AI · checking</option></select><button id="radar-clear" class="text-button">New chat</button></div><p id="radar-privacy">Built-in answers stay in this page. Chat clears on reload.</p><div id="radar-messages" role="log" aria-label="Radar conversation" aria-live="polite"></div><div class="radar-suggestions"><button>Help me choose an idea</button><button>What should I click next?</button><button>Explain the challenge</button></div><div class="radar-shortcuts"><button id="radar-lab">Go to regression lab ↗</button><button id="radar-challenge">Go to challenge ↗</button></div><form id="radar-form"><label for="radar-input">What would you like help with?</label><textarea id="radar-input" rows="2" maxlength="2000" placeholder="I’m new here. What can I build or test?" required></textarea><div><small>Enter to send · Shift+Enter for a new line</small><button id="radar-send" type="submit">Send ↑</button></div></form><p id="radar-status" role="status"></p>`;document.body.append(dialog);
const $=s=>dialog.querySelector(s);let messages=[],busy=false,destination=null;
const context=()=>Object.fromEntries([['demoStep','#action-heading'],['demoStatus','#status'],['challengeStatus','#challenge-status']].map(([key,id])=>[key,(document.querySelector(id)?.textContent||'').slice(0,1000)]));
function add(role,text,label){const item=document.createElement('article');item.className='radar-message '+role;const heading=document.createElement('small');heading.textContent=label|| (role==='user'?'YOU':'RADAR');const body=document.createElement('p');for(const part of text.split(/(\*\*[^*]+\*\*)/g)){if(role!=='user'&&part.startsWith('**')&&part.endsWith('**')){const strong=document.createElement('strong');strong.textContent=part.slice(2,-2);body.append(strong);}else body.append(document.createTextNode(part));}item.append(heading,body);const log=$('#radar-messages');log.append(item);log.scrollTop=log.scrollHeight;}
function welcome(){add('assistant','Hi, I’m Radar. Tell me what you want to build—or start with “I have no idea”. I can help you choose a small problem, understand this demo, and plan your first test.','RADAR · WELCOME');}
function modeNote(){$('#radar-privacy').textContent=$('#radar-mode').value==='live'?'Live AI sends your recent chat and visible demo status to OpenAI. Don’t include secrets. Chat clears on reload.':'Built-in help uses prepared answers in your browser. No chat is sent. Chat clears on reload.';}
function setBusy(value){busy=value;for(const el of dialog.querySelectorAll('#radar-send,#radar-clear,#radar-mode,.radar-suggestions button'))el.disabled=value;$('#radar-status').textContent=value?'Radar is thinking…':'';}
async function send(text){
  if(busy||!text.trim())return;text=text.trim().slice(0,2000);add('user',text);$('#radar-input').value='';setBusy(true);
  try{
    let reply,label;
    if($('#radar-mode').value==='guide'){reply=builtInReply(text,context());label='RADAR · BUILT-IN HELP';}
    else{const recent=[...messages,{role:'user',content:text}].slice(-11);const response=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({messages:recent,context:context()}),signal:AbortSignal.timeout(65000)});let data;try{data=await response.json();}catch{throw Error('Live chat is unavailable here. Select Built-in help or use the configured local app.');}if(!response.ok)throw Error(data.error||'Live chat failed. Please retry.');if(typeof data.reply!=='string'||!data.reply.trim())throw Error('The model returned no reply. Please retry.');reply=data.reply;label='RADAR · LIVE AI · '+data.model;}
    messages.push({role:'user',content:text},{role:'assistant',content:reply});messages=messages.slice(-10);add('assistant',reply,label);
  }catch(error){add('assistant',error.message+' Your question is restored below; retry or choose Built-in help.','RADAR · REQUEST FAILED');$('#radar-input').value=text;}finally{setBusy(false);$('#radar-input').focus();}
}
launcher.onclick=()=>{dialog.showModal();$('#radar-input').focus();};$('#radar-close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{const target=destination||launcher;destination=null;target.focus({preventScroll:true});});
$('#radar-form').onsubmit=e=>{e.preventDefault();send($('#radar-input').value);};$('#radar-input').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();send($('#radar-input').value);}};
for(const button of dialog.querySelectorAll('.radar-suggestions button'))button.onclick=()=>send(button.textContent);
$('#radar-clear').onclick=()=>{messages=[];$('#radar-messages').replaceChildren();$('#radar-input').value='';welcome();$('#radar-input').focus();};$('#radar-mode').onchange=()=>{messages=[];modeNote();add('assistant','Reply source changed. The next question starts a fresh conversation in this mode.','RADAR · SOURCE CHANGED');};
function go(selector){const el=document.querySelector(selector);destination=el.disabled?el.parentElement:el;if(el.disabled)destination.tabIndex=-1;dialog.close();el.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});}
$('#radar-lab').onclick=()=>go('#primary');$('#radar-challenge').onclick=()=>go('#challenge-freeze');
fetch('/api/config').then(r=>r.ok?r.json():null).then(config=>{const enabled=config?.chatConfigured??config?.configured;const option=$('#radar-mode option[value="live"]');option.disabled=!enabled;option.textContent=enabled?'Live AI · '+config.model:'Live AI · setup required';if(enabled&&config?.hosted&&!messages.length){$('#radar-mode').value='live';modeNote();}}).catch(()=>{$('#radar-mode option[value="live"]').textContent='Live AI · unavailable';});
welcome();modeNote();
